CREATE DATABASE `mdd_db`;
use mdd_db;
CREATE TABLE `user` (`id` int NOT NULL AUTO_INCREMENT,`username` varchar(255) NOT NULL,`email` varchar(255) NOT NULL,`password` varchar(255) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `mail` (`email`)) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `theme` (`id` int NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`content` varchar(255) NOT NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `subscription` (`theme` int DEFAULT NULL,`user` int DEFAULT NULL,`id` bigint NOT NULL AUTO_INCREMENT,PRIMARY KEY (`id`),   KEY `id_user` (`user`),KEY `id_theme` (`theme`),   CONSTRAINT `subscription_ibfk_1` FOREIGN KEY (`user`) REFERENCES `user` (`id`),   CONSTRAINT `subscription_ibfk_2` FOREIGN KEY (`theme`) REFERENCES `theme` (`id`)) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `article` (`id` int NOT NULL AUTO_INCREMENT,`title` varchar(255) NOT NULL,`content` varchar(1000) NOT NULL,`user` int DEFAULT NULL,`theme` int DEFAULT NULL,`date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),KEY `id_user` (`user`),KEY `id_theme` (`theme`),CONSTRAINT `article_ibfk_1` FOREIGN KEY (`user`) REFERENCES `user` (`id`),CONSTRAINT `article_ibfk_2` FOREIGN KEY (`theme`) REFERENCES `theme` (`id`)) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `comment` (`id` bigint NOT NULL AUTO_INCREMENT,`content` varchar(255) NOT NULL,`article` int DEFAULT NULL,`user` int DEFAULT NULL,`date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),KEY `id_user` (`user`),KEY `id_article` (`article`),CONSTRAINT `comment_ibfk_1` FOREIGN KEY (`user`) REFERENCES `user` (`id`),CONSTRAINT `comment_ibfk_2` FOREIGN KEY (`article`) REFERENCES `article` (`id`)) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;